params.code:
var day = get_tree().get_first_node_in_group('day_cycle')
var fog = get_tree().get_first_node_in_group('fog_event')
var lantern = get_tree().get_first_node_in_group('lantern')
var player = get_tree().get_first_node_in_group('player')
var stats = {}
if day:
	stats.day = day.current_day
	stats.time = day.time_of_day
	stats.is_night = day.is_night
	stats.clock = day.clock_text()
if fog:
	stats.fog_state = fog.state
	stats.fog_cycle = fog.fog_cycle
	stats.player_safe = fog.player_is_safe
if lantern:
	stats.lantern_level = lantern.level
	stats.lantern_pos = lantern.global_position
	stats.radius_tiles = lantern.get_safe_radius_tiles()
	var spr = lantern.get_node_or_null('Visuals/BaseSprite')
	stats.has_tex = spr != null and spr.texture != null
if player:
	stats.player_pos = player.global_position
	if lantern:
		stats.dx_tiles = (lantern.global_position.x - player.global_position.x) / 16.0
return stats
